const fs = require('fs');
const initSqlJs = require('/home/node/.n8n/nodes/node_modules/sql.js');
const DB_PATH = '/home/node/.n8n/assistant.db';
const SQL = await initSqlJs();
const db = new SQL.Database(fs.readFileSync(DB_PATH));

// Tasks this week
const created = db.exec("SELECT COUNT(*) FROM tasks WHERE created_at >= date('now', '-7 days')");
const completed = db.exec("SELECT COUNT(*) FROM tasks WHERE status='done' AND created_at >= date('now', '-7 days')");
const pending = db.exec("SELECT COUNT(*) FROM tasks WHERE status='pending'");
const overdue = db.exec("SELECT COUNT(*) FROM tasks WHERE status='pending' AND due_date < date('now') AND due_date IS NOT NULL");

// Reflections this week
const reflections = db.exec("SELECT date, summary, mood_signal FROM reflections WHERE date >= date('now', '-7 days') ORDER BY date");

// Expenses this week
const expenses = db.exec("SELECT SUM(amount), category FROM expenses WHERE logged_at >= date('now', '-7 days') GROUP BY category ORDER BY SUM(amount) DESC");

// Habits this week
let habitStats = [];
try {
  const r = db.exec("SELECT h.name, COUNT(CASE WHEN he.completed = 1 THEN 1 END) as done_count, h.current_streak, h.best_streak FROM habits h LEFT JOIN habit_entries he ON h.id = he.habit_id AND he.date >= date('now', '-7 days') WHERE h.is_active = 1 GROUP BY h.id");
  habitStats = r[0]?.values.map(row => ({name: row[0], done: row[1], streak: row[2], best: row[3]})) || [];
} catch(e) {}

// Mood this week
let moods = [];
try {
  const r = db.exec("SELECT mood, energy_level, DATE(logged_at) FROM mood_entries WHERE logged_at >= date('now', '-7 days') ORDER BY logged_at");
  moods = r[0]?.values.map(row => ({mood: row[0], energy: row[1], date: row[2]})) || [];
} catch(e) {}

// Contacts touched
let contacts = [];
try {
  const r = db.exec("SELECT name, last_interaction, role FROM contacts ORDER BY last_interaction DESC LIMIT 10");
  contacts = r[0]?.values.map(row => ({name: row[0], lastSeen: row[1], role: row[2]})) || [];
} catch(e) {}

// Ideas captured
let ideas = [];
try {
  const r = db.exec("SELECT title, score, status FROM ideas WHERE created_at >= date('now', '-7 days')");
  ideas = r[0]?.values.map(row => ({title: row[0], score: row[1], status: row[2]})) || [];
} catch(e) {}

// Knowledge added
let kbCount = 0;
try {
  const r = db.exec("SELECT COUNT(*) FROM knowledge_base WHERE created_at >= date('now', '-7 days')");
  kbCount = r[0]?.values[0][0] || 0;
} catch(e) {}

// Commitments
let commitments = [];
try {
  const r = db.exec("SELECT description, status, deadline FROM commitments WHERE status IN ('active', 'completed', 'broken') ORDER BY deadline");
  commitments = r[0]?.values.map(row => ({desc: row[0], status: row[1], deadline: row[2]})) || [];
} catch(e) {}

// Projects activity
let projects = [];
try {
  const r = db.exec("SELECT name, status, last_updated FROM projects WHERE status = 'active'");
  projects = r[0]?.values.map(row => ({name: row[0], status: row[1], updated: row[2]})) || [];
} catch(e) {}

db.close();

return [{
  json: {
    tasks_created: created[0]?.values[0][0] || 0,
    tasks_completed: completed[0]?.values[0][0] || 0,
    tasks_pending: pending[0]?.values[0][0] || 0,
    tasks_overdue: overdue[0]?.values[0][0] || 0,
    reflections: reflections[0]?.values.map(r => ({date: r[0], summary: r[1], mood: r[2]})) || [],
    expenses: expenses[0]?.values.map(r => ({total: r[0], category: r[1]})) || [],
    habit_stats: habitStats,
    moods: moods,
    contacts: contacts,
    ideas: ideas,
    kb_count: kbCount,
    commitments: commitments,
    projects: projects,
    chat_id: $env.TELEGRAM_CHAT_ID,
    week: new Date().toLocaleDateString('en-KE', {timeZone: 'Africa/Nairobi'})
  }
}];

